import { BaseUtils } from "../helpers/BaseUtils.js";
import {I18nTranslator} from "../helpers/I18nTranslator.js";

export const ElasticsearchModel = (function () {
    // constructor
    const my = function (overwriteParameters) {
        const me = this;

        if (!overwriteParameters) {
            overwriteParameters = {};
        }

        // *** Private instance variables ***
        // all default settings go here. Can be overwritten.
        const defaults = {
            proxyUrl: null,
            elasticsearchBaseUrl: 'http://localhost:9200/',
            elasticsearchIndex: null,
            ajaxStyle: 'vanilla'
        };

        // Extend our default options with those provided.
        // Note that the first argument to extend is an empty
        // object – this is to keep from overriding our "defaults" object.

        const m_elasticsearchModelOptions = {...defaults, ...overwriteParameters.elasticsearchModel};
        // Make sure, base url ends with a slash
        if (m_elasticsearchModelOptions.elasticsearchBaseUrl.indexOf('/', m_elasticsearchModelOptions.elasticsearchBaseUrl.length - 1) === -1) {
            m_elasticsearchModelOptions.elasticsearchBaseUrl += '/';
        }
        let m_elasticsearchVersionNumber = null;

        // This variable is only needed in server mode, so we use a dynamic import statement
        // later on to initialize this variable m_http (which is not so nice,
        // but the benefit is that we can use ElasticsearchModel in client or server mode)
        // nodejs needs something like 'import http from 'node:http';' because of its different Ajax approach
        let m_http = null;

        /******************************************************************************************************************************/
        // *** Public methods ***
        /******************************************************************************************************************************/
        this.init = function () {
            return( _storeElasticsearchVersion() );
        };

        // ***********************
        this.getElasticsearchBaseUrl = function () {
            return m_elasticsearchModelOptions.elasticsearchBaseUrl;
        };

        // ***********************
        this.getElasticsearchIndex = function () {
            return m_elasticsearchModelOptions.elasticsearchIndex;
        };

        // ***********************
        this.setElasticsearchIndex = function (newIndexName) {
            m_elasticsearchModelOptions.elasticsearchIndex = newIndexName;
        };

        // ***********************
        this.getCurrentElasticsearchType = function () {
            return '_doc';
        };
        // ***********************
        this.refresh = function (optionalIndexName) {
            return new Promise( function (resolve, reject) {
                const indexName = optionalIndexName ? optionalIndexName : me.getElasticsearchIndex();
                const action = "_refresh";
                BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Will do a refresh for index '" + indexName + "'" );
                _adjustParametersThenSendViaAjax(indexName, action, null, 'get')
                    .then( resolve() )
                    .catch( err => reject( err ) );
            } );

        };

        // ***********************
        /**
         * Scrolling in Elasticsearch is an exhausting task. First search request needs URL parameter
         * 'scroll=1m' (or similar), follow-up calls need URL parameter 'scroll=1m', too and an
         * additional path component scroll and only field _scroll_id in the request parameters.
         *
         * Note: the hook will be called with a single document as parameter, the resolve function will be called
         *       (to show iteration is finished) with no paarmeter at all)
         *
         * @param requestData             Request data for the elasticsearch search request
         * @param hookForSingleResult     hook to be called on each result of the search request. Parameter
         *                                used is an object containing the data for one document
         * @param optionalIndexName       an index name to be used instead of the default index name
         */
        this.iterateOverResultWithScrolling = function (requestData, hookForSingleResult, optionalIndexName) {
            return new Promise((resolve, reject) => {

                // we need query part "?scroll=1m" for the first query
                const additionalPath = requestData.scroll_id ? "scroll" : null;

                _pureScrollSearch( requestData, optionalIndexName, "post", "1m", additionalPath )
                    .then( function(data) {
                        //BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Data is", data );
                        if ( data.hits.hits.length > 0 ) {
                            data.hits.hits.forEach( ( x ) => {
                                // ToDo: in case of small result sizes it sometimes occurred that an element was part of data.hits.hits with
                                //       empty .source. Strange! To be investigated!
                                if ( BaseUtils.isNotEmpty(x._source) ) {
                                    hookForSingleResult( x );
                                }
                            } );
                            if ( data._scroll_id ) {
                                //BaseUtils.logMessage( BaseUtils.LogLevelType["DEBUG"], "Got scroll id", data._scroll_id );
                                me.iterateOverResultWithScrolling( { "scroll_id": data._scroll_id }, hookForSingleResult, optionalIndexName ).then(resolve).catch(reject);
                            }
